const devices=[
{id:'DEMO-AC-001',name:'空调演示设备 A',market:'市场 A',model:'演示机型 X1',status:'告警',last:'10:24',code:'E-DEMO-01',issue:'温度数据异常',temp:31.2,remote:true},
{id:'DEMO-AC-002',name:'空调演示设备 B',market:'市场 B',model:'演示机型 X2',status:'在线',last:'10:25',code:'—',issue:'无活动告警',temp:25.6,remote:true},
{id:'DEMO-AC-003',name:'空调演示设备 C',market:'市场 A',model:'演示机型 X1',status:'离线',last:'昨天 18:42',code:'E-DEMO-02',issue:'设备连接中断',temp:null,remote:false},
{id:'DEMO-AC-004',name:'空调演示设备 D',market:'市场 C',model:'演示机型 X3',status:'告警',last:'10:22',code:'E-DEMO-03',issue:'运行状态待核查',temp:29.4,remote:false},
{id:'DEMO-AC-005',name:'空调演示设备 E',market:'市场 B',model:'演示机型 X2',status:'在线',last:'10:25',code:'—',issue:'无活动告警',temp:24.8,remote:true},
{id:'DEMO-AC-006',name:'空调演示设备 F',market:'市场 C',model:'演示机型 X3',status:'在线',last:'10:23',code:'—',issue:'无活动告警',temp:26.1,remote:false}];
const state={page:'devices',selected:devices[0].id,search:'',market:'全部市场',status:'全部状态',ack:new Set(),diagnosed:false,requests:[]};
const $=s=>document.querySelector(s);
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
const tag=s=>`<span class="tag ${s==='告警'?'issue':s==='在线'?'ok':''}">${s}</span>`;
const selected=()=>devices.find(d=>d.id===state.selected);
function head(t,s,action=''){return `<div class="heading"><div><h1>${t}</h1><p>${s}</p></div>${action}</div>`}
function stats(){return `<div class="stats">${[['演示设备',6],['在线设备',5],['活动告警',3],['待审批申请',state.requests.length]].map(([t,n])=>`<div class="stat"><span>${t} · 模拟</span><strong>${n}</strong></div>`).join('')}</div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#content').innerHTML=({devices:devicePage,alarms:alarmPage,diagnosis:diagnosisPage,permissions:permissionPage})[state.page](); bind();}
function devicePage(){const rows=devices.filter(d=>(d.id+' '+d.name+' '+d.model).toLowerCase().includes(state.search.toLowerCase())&&(state.market==='全部市场'||d.market===state.market)&&(state.status==='全部状态'||d.status===state.status));return head('设备中心','按设备与市场定位问题，查看运行信息并进入排查任务。')+stats()+`<section class="panel"><form id="filter" class="filters"><label>设备名称或编号<input id="search" placeholder="搜索演示设备" value="${escapeHTML(state.search)}"></label><label>所属市场<select id="market">${['全部市场','市场 A','市场 B','市场 C'].map(x=>`<option ${x===state.market?'selected':''}>${x}</option>`).join('')}</select></label><label>运行状态<select id="status">${['全部状态','在线','告警','离线'].map(x=>`<option ${x===state.status?'selected':''}>${x}</option>`).join('')}</select></label><button class="primary">查询</button><button type="button" id="reset">重置</button></form><div class="list-meta"><span>设备列表 / ${rows.length}条</span><span>数据截止：演示时间 10:25</span></div><div class="table-scroll"><table><thead><tr><th>设备</th><th>市场 / 机型</th><th>状态</th><th>最近上报</th><th>远程能力</th><th>操作</th></tr></thead><tbody>${rows.map(d=>`<tr><td><div class="device-name">${d.name}</div><div class="subtext">${d.id}</div></td><td>${d.market}<div class="subtext">${d.model}</div></td><td>${tag(d.status)}</td><td>${d.last}</td><td>${d.remote?'支持工程模式':'仅数据查询'}</td><td><button class="text-btn" data-detail="${d.id}">详情</button><button class="text-btn" data-diagnose="${d.id}">排查</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">没有匹配设备，请调整筛选条件。</td></tr>'}</tbody></table></div></section>`}
function alarmPage(){return head('告警中心','先明确告警状态，再进入对应设备的排查任务。')+`<section class="panel"><h2>待处理告警</h2><p class="muted">确认告警表示已查看，不等于故障已解决。</p><div class="table-scroll"><table><thead><tr><th>告警 / 设备</th><th>等级</th><th>业务状态</th><th>发现时间</th><th>操作</th></tr></thead><tbody>${devices.filter(d=>d.code!=='—').map(d=>`<tr><td><b>${d.issue}</b><div class="subtext">${d.code} · ${d.id}</div></td><td><span class="tag issue">${d.status==='离线'?'需关注':'需排查'}</span></td><td>${state.ack.has(d.id)?'已确认 / 待排查':'未确认'}</td><td>${d.last}</td><td><button class="text-btn" data-ack="${d.id}" ${state.ack.has(d.id)?'disabled':''}>${state.ack.has(d.id)?'已确认':'确认告警'}</button><button class="text-btn" data-diagnose="${d.id}">进入排查</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>处理规则</h2><p>查看告警 → 确认已接收 → 进入设备排查 → 记录处理结果。本演示只模拟告警确认与排查衔接，不模拟真实故障清除。</p></section>`}
function trend(){return `<svg class="trend" viewBox="0 0 600 160" role="img" aria-label="模拟温度变化趋势，最近数次采样逐渐升高"><g stroke="#e4e7ed" fill="none"><path d="M30 20H580M30 70H580M30 120H580"/></g><g fill="#7b8390" font-size="11"><text x="0" y="24">32</text><text x="0" y="74">28</text><text x="0" y="124">24</text><text x="30" y="150">10:00</text><text x="280" y="150">10:12</text><text x="540" y="150">10:24</text></g><path d="M30 118L90 112L150 115L210 92L270 84L330 73L390 48L450 53L510 30L580 24" fill="none" stroke="#285bd4" stroke-width="2.5"/></svg>`}
function diagnosisPage(){const d=selected();return head('远程诊断','围绕设备信息、数据与故障线索完成排查。',`<button id="back-device">返回设备中心</button>`)+`<div class="steps"><span class="current">1 确认设备</span><span class="${state.diagnosed?'current':''}">2 分析线索</span><span>3 权限与处理</span><span>4 记录反馈</span></div><div class="two-col"><div><section class="panel"><h2>${d.name}　${tag(d.status)}</h2><p class="muted">${d.id} / ${d.market} / ${d.model}</p><div class="metric-row"><div><span>温度示例</span><strong>${d.temp===null?'暂无数据':d.temp+' °C'}</strong></div><div><span>数据状态</span><strong style="font-size:16px">${d.status==='离线'?'上报中断':'最近上报 '+d.last}</strong></div></div>${d.temp===null?'<div class="empty">设备离线，暂无实时趋势。请先核查连接状态。</div>':trend()}<p class="subtext">趋势、数值与阈值仅为界面演示，不用于真实维修判断。</p></section><section class="panel"><h2>排查辅助</h2><p>当前线索：${d.issue}。点击后展示预设的演示排查建议。</p><button id="analyze" class="primary">${state.diagnosed?'重新生成演示建议':'生成演示排查建议'}</button>${state.diagnosed?`<div class="result"><h3>建议核查顺序</h3><ol><li>核对设备身份与数据更新时间。</li><li>${d.status==='离线'?'检查网络与设备上报状态，恢复连接后重新读取数据。':'核对异常数据是否持续出现，并结合运行状态排查。'}</li><li>必要时由具备权限的工程师进一步处理。</li></ol><p class="muted">知识来源：本作品预设演示条目 DEMO-KB-01。此处无大模型调用，建议并非维修指导。</p><label>记录本次反馈<select id="feedback"><option value="">请选择</option><option>线索有帮助，继续核查</option><option>信息不足，需要人工支持</option></select></label><button id="save-feedback" class="secondary" style="margin-top:12px">记录反馈</button></div>`:''}</section></div><div><section class="panel"><h2>当前故障线索</h2><p><span class="tag issue">${d.code}</span></p><p>${d.issue}</p><h3>排查记录</h3><ol class="timeline"><li>进入设备排查工作台</li><li>${state.ack.has(d.id)?'告警已确认':'等待工程师确认与核查'}</li><li>${state.diagnosed?'已生成演示排查建议':'等待分析线索'}</li></ol></section><section class="panel"><h2>远程工程模式</h2><p>${d.remote?'该演示设备支持远程工程模式。当前角色只有查询权限，需要申请临时操作权限。':'该演示设备不支持远程工程模式，可查询数据并转人工排查。'}</p><button class="primary" id="apply" ${d.remote?'':'disabled'}>申请操作权限</button><p class="subtext">不包含真实控制指令或真实参数下发。</p></section></div></div>`}
function permissionPage(){return head('权限管理','通过角色范围与临时授权说明平台的操作边界。')+`<section class="panel"><h2>角色与能力示意</h2><div class="permission-grid"><article><h3>售后管理者</h3><p>查看业务范围内设备与告警；处理授权申请。</p></article><article><h3>服务商</h3><p>查看所属服务范围内的设备与处理记录。</p></article><article><h3>维修工程师</h3><p>查询设备数据；按任务申请临时操作权限。</p></article></div><p class="subtext">脱敏重绘。此处为独立演示权限方案，不是实际企业权限矩阵。</p></section><section class="panel"><h2>我的临时授权申请</h2><div class="table-scroll"><table><thead><tr><th>设备</th><th>权限范围</th><th>授权时长</th><th>申请原因</th><th>状态</th></tr></thead><tbody>${state.requests.map(r=>`<tr><td>${r.device}</td><td>远程工程模式</td><td>${r.duration}</td><td style="white-space:normal;max-width:280px">${escapeHTML(r.reason)}</td><td><span class="tag issue">待审批</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无申请。可在设备排查页申请临时操作权限。</td></tr>'}</tbody></table></div></section>`}
function go(page,id){state.page=page;if(id){state.selected=id;state.diagnosed=false}render();window.scrollTo(0,0)}
function bind(){
document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const d=devices.find(x=>x.id===b.dataset.detail);$('#detail-body').innerHTML=`<h2>${d.name}</h2><p>${d.id}　${tag(d.status)}</p><p>市场：${d.market}<br>机型：${d.model}<br>最近上报：${d.last}<br>远程能力：${d.remote?'支持工程模式':'仅查询'}<br>告警线索：${d.issue}</p><p class="muted">所有设备信息均为模拟数据。</p><button class="primary" id="detail-diagnose">进入远程诊断</button>`;$('#detail-diagnose').onclick=()=>{$('#detail').close();go('diagnosis',d.id)};$('#detail').showModal()});
document.querySelectorAll('[data-diagnose]').forEach(b=>b.onclick=()=>go('diagnosis',b.dataset.diagnose));
document.querySelectorAll('[data-ack]').forEach(b=>b.onclick=()=>{state.ack.add(b.dataset.ack);render();toast('已确认告警，故障仍需排查')});
if($('#filter')){$('#filter').onsubmit=e=>{e.preventDefault();state.search=$('#search').value;state.market=$('#market').value;state.status=$('#status').value;render()};$('#reset').onclick=()=>{state.search='';state.market='全部市场';state.status='全部状态';render()}}
if($('#analyze'))$('#analyze').onclick=()=>{state.diagnosed=true;render()};
if($('#save-feedback'))$('#save-feedback').onclick=()=>{if(!$('#feedback').value){toast('请先选择反馈');return}toast('已记录本次演示反馈')};
if($('#back-device'))$('#back-device').onclick=()=>go('devices');
if($('#apply'))$('#apply').onclick=()=>{$('#request-device').textContent=state.selected;$('#request').showModal()};
}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));
$('#cancel-request').onclick=()=>$('#request').close();
$('#request-form').onsubmit=e=>{e.preventDefault();const reason=$('#reason').value.trim();if(reason.length<5){toast('请填写至少5字的申请原因');return}state.requests.push({device:state.selected,duration:$('#duration').value,reason});$('#request').close();$('#reason').value='';go('permissions');toast('演示申请已提交，等待审批')};
render();
